-- ============================================================
-- Carga de productos -> negocio 35c5076a-bd85-4a1b-8d1c-ce719c4f9ae6
-- 2599 productos vendibles | 21 categorias
-- Impuestos: ITBIS 18% + LEY 10% (ambos INCLUSIVOS) por producto
-- Idempotente: puede re-ejecutarse sin duplicar.
-- Correr en Supabase Studio (SQL Editor) o psql.
-- ============================================================
begin;

-- Salvaguarda: el negocio debe tener EXACTAMENTE los 2 impuestos esperados.
do $$
declare n int;
begin
  select count(*) into n from public.taxes
   where business_id = '35c5076a-bd85-4a1b-8d1c-ce719c4f9ae6' and name in ('ITBIS','LEY')
     and coalesce(is_active,true);
  if n <> 2 then
    raise exception 'Se esperaban 2 impuestos activos (ITBIS, LEY), hay %', n;
  end if;
end $$;

-- 1) Categorias (crea solo las que falten)
insert into public.categories (id, business_id, name, position, is_active)
select gen_random_uuid(), '35c5076a-bd85-4a1b-8d1c-ce719c4f9ae6'::uuid, v.name, v.pos, true
from (values
  ('CAFE', 1),
  ('CERVEZAS', 2),
  ('COCTELES', 3),
  ('CROISSANTS', 4),
  ('DESAYUNO', 5),
  ('FRAPPE', 6),
  ('GINEBRAS', 7),
  ('GUARNICIONES', 8),
  ('JUGOS/ FROZEN', 9),
  ('PA'' COMER', 10),
  ('PA'' COMPARTIR', 11),
  ('PA'' PICAR', 12),
  ('POSTRES', 13),
  ('RON', 14),
  ('SANDWICHES', 15),
  ('TEQUILA', 16),
  ('TIENDA', 17),
  ('TRAGOS', 18),
  ('VINOS', 19),
  ('VODKA', 20),
  ('WHISKY', 21)
) as v(name, pos)
where not exists (
  select 1 from public.categories c
  where c.business_id = '35c5076a-bd85-4a1b-8d1c-ce719c4f9ae6'::uuid and c.name = v.name
);

-- 2) Staging de productos
create temp table _stage (
  codigo text, name text, price numeric, cost numeric,
  dept text, barcode text
) on commit drop;

