-- 3) UPSERT: actualizar productos que YA existen (match por sku)
--    Sobrescribe nombre, precio, costo, categoria y barcode con el archivo,
--    y los deja en tax_mode = 'inclusive'.
update public.menu_items mi
set name        = s.name,
    price       = s.price,
    cost        = s.cost,
    barcode     = s.barcode,
    category_id = c.id,
    tax_mode    = 'inclusive',
    updated_at  = now()
from _stage s
left join public.categories c
  on c.business_id = '35c5076a-bd85-4a1b-8d1c-ce719c4f9ae6'::uuid and c.name = s.dept
where mi.business_id = '35c5076a-bd85-4a1b-8d1c-ce719c4f9ae6'::uuid
  and mi.sku = s.codigo;

-- 4) Insertar productos nuevos (sku que aun no existe)
insert into public.menu_items
  (business_id, category_id, name, price, cost, tax_mode, sku, barcode, is_active)
select '35c5076a-bd85-4a1b-8d1c-ce719c4f9ae6'::uuid, c.id, s.name, s.price, s.cost, 'inclusive',
       s.codigo, s.barcode, true
from _stage s
left join public.categories c
  on c.business_id = '35c5076a-bd85-4a1b-8d1c-ce719c4f9ae6'::uuid and c.name = s.dept
where not exists (
  select 1 from public.menu_items mi
  where mi.business_id = '35c5076a-bd85-4a1b-8d1c-ce719c4f9ae6'::uuid and mi.sku = s.codigo
);

-- 5) Asegurar que TODO el catalogo del negocio quede inclusive
--    (incluye productos que no venian en el archivo)
update public.menu_items
set tax_mode = 'inclusive', updated_at = now()
where business_id = '35c5076a-bd85-4a1b-8d1c-ce719c4f9ae6'::uuid
  and tax_mode is distinct from 'inclusive';

-- 6) Enlazar ITBIS + LEY (inclusivos) a cada producto del archivo
insert into public.menu_item_taxes (item_id, tax_id)
select mi.id, t.id
from public.menu_items mi
join _stage s on s.codigo = mi.sku
join public.taxes t
  on t.business_id = mi.business_id and t.name in ('ITBIS','LEY')
where mi.business_id = '35c5076a-bd85-4a1b-8d1c-ce719c4f9ae6'::uuid
on conflict do nothing;

-- 7) Menu 'MENU PRINCIPAL' (crea si no existe)
insert into public.menus (id, business_id, name, is_active)
select gen_random_uuid(), '35c5076a-bd85-4a1b-8d1c-ce719c4f9ae6'::uuid, 'MENU PRINCIPAL', true
where not exists (
  select 1 from public.menus m
  where m.business_id = '35c5076a-bd85-4a1b-8d1c-ce719c4f9ae6'::uuid and m.name = 'MENU PRINCIPAL'
);

-- 8) Vincular TODO el catalogo del negocio al MENU PRINCIPAL
insert into public.menu_item_links (menu_id, item_id, position)
select m.id, mi.id,
       row_number() over (order by mi.category_id nulls last, mi.name)
from public.menu_items mi
join public.menus m
  on m.business_id = mi.business_id and m.name = 'MENU PRINCIPAL'
where mi.business_id = '35c5076a-bd85-4a1b-8d1c-ce719c4f9ae6'::uuid
on conflict do nothing;

-- 9) Resumen de control
select
  (select count(*) from public.menu_items
     where business_id = '35c5076a-bd85-4a1b-8d1c-ce719c4f9ae6'::uuid) as total_items,
  (select count(*) from public.menu_items
     where business_id = '35c5076a-bd85-4a1b-8d1c-ce719c4f9ae6'::uuid and tax_mode <> 'inclusive') as no_inclusive,
  (select count(*) from public.menu_item_taxes mit
     join public.menu_items mi on mi.id = mit.item_id
     where mi.business_id = '35c5076a-bd85-4a1b-8d1c-ce719c4f9ae6'::uuid) as total_links_impuesto,
  (select count(*) from public.categories
     where business_id = '35c5076a-bd85-4a1b-8d1c-ce719c4f9ae6'::uuid) as total_categorias,
  (select count(*) from public.menu_item_links mil
     join public.menus m on m.id = mil.menu_id
     where m.business_id = '35c5076a-bd85-4a1b-8d1c-ce719c4f9ae6'::uuid
       and m.name = 'MENU PRINCIPAL') as items_en_menu_principal;

commit;
